void TIM1_PWM_Init(void) {
    // 1. Enable GPIOA and TIM1 clocks
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    // 2. Configure PA8 as Alternate Function (AF6 for TIM1_CH1)
    // Mode: Alternate function (10), Speed: Very high (11)
    GPIOA->MODER &= ~(GPIO_MODER_MODE8_Msk);
    GPIOA->MODER |=  (2UL << GPIO_MODER_MODE8_Pos);
    GPIOA->OSPEEDR |= (3UL << GPIO_OSPEEDR_OSPEED8_Pos);

    // Select AF6 in AFRH for pin 8 (AFRL/AFRH mapping: PA8 is AFRH[0])
    GPIOA->AFR[1] &= ~(GPIO_AFRH_AFSEL8_Msk);
    GPIOA->AFR[1] |=  (6UL << GPIO_AFRH_AFSEL8_Pos);

    // 3. Configure TIM1 for 20 kHz Edge-Aligned PWM Mode 1
    // Timer clock (PCLK2) = 170 MHz
    // Frequency = 20 kHz => Period = 170,000,000 / 20,000 = 8500 counts
    TIM1->PSC = 0;                     // No prescaler (170 MHz timer clock)
    TIM1->ARR = 8500 - 1;              // 20 kHz period

    // 25% Duty Cycle => CCR1 = 8500 * 0.25 = 2125
    TIM1->CCR1 = 2125;

