    GPIOA->MODER |=  (GPIO_MODER_MODE8_1);       // Alternate function mode
    GPIOA->OTYPER &= ~(GPIO_OTYPER_TI8_0);        // Push-pull
    GPIOA->OSPEEDR |= (GPIO_OSPEEDR_OSPEED8);     // High speed
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD8);          // No pull-up, no pull-down

    // Connect PA8 to AF6 (TIM1_CH1) in Alternate Function High Register
    GPIOA->AFR[1] &= ~(GPIO_AFRH_AFSEL8);
    GPIOA->AFR[1] |=  (6U << GPIO_AFRH_AFSEL8_Pos);

    // 3. Configure TIM1 Base for 20 kHz PWM at 170 MHz F_CPU
    TIM1->PSC = 0;                     // No prescaler
    TIM1->ARR = 8499;                  // Auto-reload value for 20 kHz

    // 4. Configure TIM1 Channel 1 for PWM Mode 1 (active-high)
    TIM1->CCMR1 &= ~(TIM_CCMR1_CC1S);  // CC1 channel configured as output
    TIM1->CCMR1 &= ~(TIM_CCMR1_OC1M);
    TIM1->CCMR1 |=  (TIM_CCMR1_OC1M_1 | TIM_CCMR1_OC1M_2); // PWM mode 1
    TIM1->CCMR1 |=  (TIM_CCMR1_OC1PE);

    // 5. Set Duty Cycle to 25% (CCR1 = 2124)
    TIM1->CCR1 = 2124;

    // 6. Configure Output Enable and Polarity
    TIM1->CCER &= ~(TIM_CCER_CC1P);    // Active high polarity
    TIM1->CCER |=  (TIM_CCER_CC1E);    // Enable channel 1 output

    // 7. Enable Main Output (MOE) required for advanced timers like TIM1
    TIM1->BDTR |=  (TIM_BDTR_MOE);

    // 8. Enable Timer 1 Counter
    TIM1->CR1 |=  (TIM_CR1_CEN);
}

void I2C3_Init(void) {
    // 1. Enable GPIOC and I2C3 clocks
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    // 2. Configure PC0 (SCL) and PC1 (SDA) as Alternate Function Open-Drain
    GPIOC->MODER &= ~(GPIO_MODER_MODE0 | GPIO_MODER_MODE1);
    GPIOC->MODER |=  (GPIO_MODER_MODE0_1 | GPIO_MODER_MODE1_1);

    GPIOC->OTYPER |= (GPIO_OTYPER_TI0 | GPIO_OTYPER_TI1);
    GPIOC->OSPEEDR |= (GPIO_OSPEEDR_OSPEED0 | GPIO_OSPEEDR_OSPEED1);
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD0 | GPIO_PUPDR_PUPD1);

    // Connect PC0 and PC1 to AF4 (I2C3_SCL / I2C3_SDA) in AFRL
    GPIOC->AFR[0] &= ~((0xF << (0 * 4)) | (0xF << (1 * 4)));
    GPIOC->AFR[0] |=  ((4U << (0 * 4)) | (4U << (1 * 4)));

    // 3. Configure I2C3 Timing for 100 kHz standard mode with PCLK1 = 170 MHz
    I2C3->CR1 &= ~I2C3_CR1_PE; // Ensure I2C3 is disabled while configuring TIMINGR

    I2C3->TIMINGR = (3U << I2C3_TIMINGR_PRESC_Pos) |
                    (3U << I2C3_TIMINGR_SCLDEL_Pos) |
                    (1U << I2C3_TIMINGR_SDADEL_Pos) |
                    (199U << I2C3_TIMINGR_SCLH_Pos) |
                    (199U << I2C3_TIMINGR_SCLL_Pos);

    // 4. Enable I2C3 Peripheral
    I2C3->CR1 |= I2C3_CR1_PE;
}

int main(void) {
    // Initialize TIM1 for 20 kHz PWM on PA8
    TIM1_PWM_Init();

    // Initialize I2C3 for 100 kHz controller mode on PC0/PC1
    I2C3_Init();

    // Infinite loop
    while (1) {
        // Background tasks can go here
    }
}
```

### Explanation
1. **`TIM1_PWM_Init` function:** Sets up PA8 as an alternate function pin (AF6) connected to TIM1 Channel 1, configures the timer time base for a 20 kHz frequency (170 MHz clock, ARR = 8499, PSC = 0), sets the duty cycle to 25% via CCR1 = 2124, enables outputs (`CCER` and `BDTR->MOE`), and starts the timer.
2. **`I2C3_Init` function:** Configures PC0 and PC1 as open-drain alternate function pins (AF4) with internal pull-ups disabled for external 1.8V level shifting. It then programs the `TIMINGR` register while I2C3 is disabled (`PE = 0`) to establish a 100 kHz standard-mode clock from the 170 MHz PCLK1, and finally enables the peripheral.
3. **`main` function:** Calls both initialization routines sequentially and enters an empty `while (1)` busy-wait loop.

