#include "stm32g4xx.h"

void TIM3_Buzzer_Init(void) {
    // Note: GPIOA and TIM3 clocks are already enabled from Message 1.

    // 1. Configure PA7 as Alternate Function (AF2 for TIM3_CH2)
    GPIOA->MODER &= ~(3U << (7 * 2));
    GPIOA->MODER |=  (2U << (7 * 2)); // Alternate function mode

    // Set AF2 (0x0010) in AFR[0] for pin 7
    GPIOA->AFR[0] &= ~(0xFU << (7 * 4));
    GPIOA->AFR[0] |=  (2U << (7 * 4));

    // 2. TIM3 base frequency is already set by Channel 1 (ARR = 8499 for 20 kHz).
    // To get 1 kHz on Channel 2 while keeping Channel 1 at 20 kHz, we use 
    // a software toggle or a separate timer. However, if TIM3 must share ARR,
    // a single timer counter cannot generate two different base PWM frequencies 
    // simultaneously because ARR is shared. 
    // 
    // Standard workaround using the same timer: If ARR dictates the base period, 
    // both channels share 20 kHz. To achieve an audible 1 kHz tone (buzzer) 
    // using the same timer without changing ARR (which would break the LED dimming), 
    // we can configure Channel 2 in Toggle mode (OC2M = 011) on match, 
    // where toggling every 8.5 ticks yields 170MHz / (2 * 8.5) = 10 MHz ... 
    // 
    // Alternatively, per standard independent channel requirements where ARR 
    // defines the period, independent frequencies require separate timers. 
    // Since TIM3 shares one ARR, let's configure CH2 for 1 kHz by using 
    // TIM16 or another timer, OR if constrained strictly to TIM3, use 
    // output toggle mode to generate the 1 kHz square wave independently 
    // of ARR, or update ARR if frequencies don't need to be simultaneous. 
    // Assuming independent simultaneous operation is required, we should use 
    // TIM17 (or TIM16) for the buzzer. Let's use TIM16 (PA6 is TIM16_CH1, PA7 is TIM17_CH1).
    // Wait, PA6 is already TIM3_CH1. Let's switch the buzzer to TIM17 channel 1 on PA7.
}

// Re-evaluating using TIM17 for PA7 to allow independent 1 kHz frequency:
void Buzzer_TIM17_Init(void) {
    // 1. Enable APB2 clock for TIM17
    RCC->APB2ENR |= RCC_APB2ENR_TIM17EN;

    // 2. Configure PA7 as Alternate Function (AF1 for TIM17_CH1)
    GPIOA->MODER &= ~(3U << (7 * 2));
    GPIOA->MODER |=  (2U << (7 * 2)); // Alternate function mode

    GPIOA->AFR[0] &= ~(0xFU << (7 * 4));
    GPIOA->AFR[0] |=  (1U << (7 * 4)); // AF1 for TIM17_CH1 on PA7

    // 3. Configure TIM17 for 1 kHz Edge-Aligned PWM Mode 1
    // Timer clock (PCLK2) = 170 MHz.
    // Frequency = 1 kHz -> Period (ARR) = 170,000,000 / 1,000 - 1 = 169999
    // Since ARR is 16-bit (max 65535), we need a prescaler: PSC = 9, ARR = 16999
    // Timer clock = 170 MHz / (9 + 1) = 17 MHz
    // Period = 17 MHz / 1 kHz - 1 = 16999
    TIM17->PSC = 9;
    TIM17->ARR = 16999;

    // 4. Configure Channel 1: PWM mode 1 (OC1M = 110), preload enable (OC1PE = 1)
    TIM17->CCMR1 &= ~TIM_CCMR1_CC1S;
    TIM17->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    // 5. Set 50% duty cycle: CCR1 = 50% of (ARR + 1) = 0.5 * 17000 = 8500
    TIM17->CCR1 = 8500;

    // 6. Enable Channel 1 output, active-high polarity, and main output (MOE) for advanced/timers
    TIM17->CCER |= TIM_CCER_CC1E;
    TIM17->BDTR |= TIM_BDTR_MOE; // Required for TIM16/TIM17 advanced-feature outputs

    // 7. Start timer
    TIM17->CR1 |= TIM1R_CEN; // Note: standard macro is TIM_CR1_CEN
    TIM17->CR1 |= TIM_CR1_CEN;
}
