    // Timer clock for TIM3 is PCLK1 = 170 MHz (APB1 prescaler = 1, so timer clock = PCLK1 * 1 = 170 MHz)
    // Formula: Frequency = Timer_Clock / ((PSC + 1) * (ARR + 1))
    // Let ARR = 8499, then Timer_Clock / (ARR + 1) = 170,000,000 / 8500 = 20,000 Hz.
    // Thus PSC = 0.
    TIM3->PSC = 0;
    TIM3->ARR = 8499;

    // 4. Configure Channel 1 for PWM Mode 1 (OCM = 110: active as long as CNT < CCR1)
    // CCMR1: CC1S = 00 (output), OC1M = 110 (PWM mode 1)
    TIM3->CCMR1 &= ~TIM_CCMR1_CC1S;
    TIM3->CCMR1 &= ~TIM_CCMR1_OC1M;
    TIM3->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos);
    TIM3->CCMR1 |= TIM_CCMR1_OC1PE; // Enable preload register

