    GPIOA->MODER |=  ((2U << (2 * 2)) | (2U << (3 * 2)));

    // Set high speed for PA2 and PA3
    GPIOA->OSPEEDR |= (3U << (2 * 2)) | (3U << (3 * 2));

    // Configure AFRL for PA2 and PA3 to AF7 (0111)
    GPIOA->AFR[0] &= ~((0xFU << (4 * 2)) | (0xFU << (4 * 3)));
    GPIOA->AFR[0] |=  ((7U   << (4 * 2)) | (7U   << (4 * 3)));

    // 3. Configure USART1
    // Baud rate calculation: 
