    GPIOC->MODER |= (GPIO_MODER_MODE4_1 | GPIO_MODER_MODE5_1);

    GPIOC->AFR[0] &= ~((0xF << (4 * 4)) | (0xF << (4 * 5)));
    GPIOC->AFR[0] |=  ((7 << (4 * 4)) | (7 << (4 * 5)));

