#include "stm32g4xx.h"

int main(void) {
    // 1. Clock Tree Configuration (170 MHz SYSCLK from 16 MHz HSE)
    // Enable Flash latency (4 WS) and prefetch
    FLASH->ACR = FLASH_ACR_LATENCY_4WS | FLASH_ACR_PRFTEN | FLASH_ACR_ICEN | FLASH_ACR_DCEN;

    // Set Voltage Scaling Range 1
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    PWR->CR1 &= ~PWR_CR1_VOS;
    PWR->CR1 |= (1U << PWR_CR1_VOS_Pos); // VOS = 0b01 (Range 1)

    // Enable HSE
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY));

    // Configure PLL: Source=HSE (16 MHz), M=4, N=85, R=2 -> SYSCLK = (16/4)*85 / 2 = 170 MHz
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE |
                   (3U << RCC_PLLCFGR_PLLM_Pos) |     // M = 4 (val 3)
                   (85U << RCC_PLLCFGR_PLLN_Pos) |    // N = 85
                   (0U << RCC_PLLCFGR_PLLR_Pos) |     // R = 2 (val 0)
                   RCC_PLLCFGR_PLLREN;               // Enable PLLR output

    // Enable PLL
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    // Select PLL as system clock source
    RCC->CFGR &= ~RCC_CFGR_SW;
    RCC->CFGR |= RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

    // AHB, APB1, APB2 prescalers = 1 (HCLK = PCLK1 = PCLK2 = 170 MHz)
    RCC->CFGR &= ~(RCC_CFGR_HPRE | RCC_CFGR_PPRE1 | RCC_CFGR_PPRE2);

    // 2. GPIO Configuration
    // Enable GPIOA and GPIOC clocks
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN;

    // USART2: PA2 (TX), PA3 (RX) -> Alternate Function AF7
    GPIOA->MODER &= ~((3U << (2 * 2)) | (3U << (3 * 2)));
    GPIOA->MODER |=  ((2U << (2 * 2)) | (2U << (3 * 2))); // AF mode
    GPIOA->AFR[0] &= ~((0xFU << (2 * 4)) | (0xFU << (3 * 4)));
    GPIOA->AFR[0] |=  ((7U << (2 * 4)) | (7U << (3 * 4)));  // AF7 for USART2

    // I2C3: PA8 (SCL), PC9 (SDA) -> Alternate Function AF4, Open-Drain
    GPIOA->MODER &= ~(3U << (8 * 2));
    GPIOA->MODER |=  (2U << (8 * 2)); // AF mode
    GPIOA->OTYPER |= (1U << 8);       // Open-drain
    GPIOA->AFR[1] &= ~(0xFU << ((8 - 8) * 4));
    GPIOA->AFR[1] |=  (4U << ((8 - 8) * 4));  // AF4 for I2C3

    GPIOC->MODER &= ~(3U << (9 * 2));
    GPIOC->MODER |=  (2U << (9 * 2)); // AF mode
    GPIOC->OTYPER |= (1U << 9);       // Open-drain
    GPIOC->AFR[1] &= ~(0xFU << ((9 - 8) * 4));
    GPIOC->AFR[1] |=  (4U << ((9 - 8) * 4));  // AF4 for I2C3

    // 3. USART2 Configuration (1 Mbaud @ 170 MHz PCLK1, 8N1)
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN;
    USART2->BRR = 170; // 170 MHz / 1,000,000 = 170
    USART2->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE; // Enable TX, RX, USART

    // 4. I2C3 Configuration (Standard Mode, 100 kHz @ 170 MHz PCLK1)
    RCC->APB1ENR2 |= RCC_APB1ENR2_I2C3EN;
    I2C3->CR1 &= ~I2C_CR1_PE; // Disable I2C before config
    // Timing for 100 kHz with 170 MHz input (PRESC=16, SCLL=49, SCLH=47, SDADEL=2, SCLDEL=3)
    I2C3->TIMINGR = (16U << I2C_TIMINGR_PRESC_Pos) |
                    (3U  << I2C_TIMINGR_SCLDEL_Pos) |
                    (2U  << I2C_TIMINGR_SDADEL_Pos) |
                    (47U << I2C_TIMINGR_SCLH_Pos)  |
                    (49U << I2C_TIMINGR_SCLL_Pos);
    I2C3->CR1 |= I2C_CR1_PE; // Enable I2C3

    // Main loop
    while (1) {
        // Application tasks and low-power entry handled here
    }
}
```

